const fs = require('fs');
const { execFileSync } = require('child_process');

const IMG = new Set(['jpg','jpeg','png','gif','webp','bmp','heic']);
const PDF = new Set(['pdf']);
const DOC = new Set(['txt','csv','doc','docx','rtf','odt','md']);
const CAT = {
  invoice:  { folder: 'فواتير', prefix: 'فاتورة' },
  contract: { folder: 'عقود',   prefix: 'عقد' },
  photo:    { folder: 'صور',    prefix: 'صورة' },
  other:    { folder: 'أخرى',   prefix: 'ملف' },
};
const UNDATED = 'غير-مؤرّخ';
const pad2 = n => String(n).padStart(2, '0');

// strip bidi control marks + tatweel so Arabic keywords match cleanly
const stripBidi = s => (s || '').replace(/[‎‏‪-‮ـ]/g, '');

// read the PDF's own text with poppler (the LibreOffice-made PDFs carry a clean text layer)
function pdfText(name) {
  try { return execFileSync('pdftotext', ['downloads/' + name, '-'],
                            { encoding: 'utf8', maxBuffer: 20971520 }); }
  catch (e) { return ''; }
}

// a date from any string, robust to bidi reversal (D-M-Y or Y-M-D). Month = middle group.
function parseDate(text) {
  const t = text || '';
  let m = t.match(/(?<!\d)(20\d\d)(\d\d)(\d\d)(?!\d)/);   // compact YYYYMMDD (IMG_20260311)
  let y, mo, d;
  if (m) { y = m[1]; mo = m[2]; d = m[3]; }
  else {
    m = t.match(/(\d{2,4})[-\/_.](\d{1,2})[-\/_.](\d{2,4})/);
    if (!m) return null;
    const a = m[1], mid = m[2], c = m[3];
    if (a.length === 4) { y = a; d = c; }
    else if (c.length === 4) { y = c; d = a; }
    else return null;
    mo = mid;
  }
  const yi = +y, moi = +mo, di = +d;
  if (!(yi >= 2000 && yi <= 2099 && moi >= 1 && moi <= 12 && di >= 1 && di <= 31)) return null;
  return String(yi).padStart(4, '0') + '-' + pad2(moi) + '-' + pad2(di);
}

const items = $input.all();
// stable order by original file name, so the clean numbering is reproducible
const order = items.map((it, idx) => ({ idx, name: it.binary.data.fileName }))
  .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

const counters = { invoice: 0, contract: 0, photo: 0, other: 0 };
const dirs = new Set();
const out = [];
for (const o of order) {
  const it = items[o.idx];
  const name = it.binary.data.fileName;
  const ext = (name.includes('.') ? name.split('.').pop() : '').toLowerCase();
  let category, dateSrc;
  if (IMG.has(ext)) { category = 'photo'; dateSrc = name; }
  else if (PDF.has(ext)) {
    const text = stripBidi(pdfText(name));
    if (text.indexOf('فاتورة') >= 0 || /invoice/i.test(text)) category = 'invoice';
    else if (text.indexOf('عقد') >= 0 || /contract/i.test(text)) category = 'contract';
    else category = 'other';
    dateSrc = text + ' ' + name;
  }
  else if (DOC.has(ext)) { category = 'other'; dateSrc = name; }
  else { category = 'other'; dateSrc = name; }

  const iso = parseDate(dateSrc);
  counters[category] += 1;
  const seq = pad2(counters[category]);
  const c = CAT[category];
  let folder, newname;
  if (iso) { folder = c.folder + '/' + iso.slice(0, 7); newname = c.prefix + '-' + iso + '-' + seq + '.' + ext; }
  else { folder = c.folder + '/' + UNDATED; newname = c.prefix + '-' + seq + '.' + ext; }
  dirs.add(folder);
  out.push({
    json: {
      'الملف الأصلي': name, 'التصنيف': c.folder, 'التاريخ': iso || '',
      'المجلد الجديد': folder, 'الاسم الجديد': newname,
      folder: folder, newname: newname, category: category,
    },
    binary: it.binary,
  });
}
// the Write node does not create missing parent folders, so make them here
for (const f of dirs) { fs.mkdirSync('sorted/' + f, { recursive: true }); }
return out;

return $input.all().map(it => {
  const j = it.json;
  return { json: {
    'الملف الأصلي': j['الملف الأصلي'],
    'التصنيف': j['التصنيف'],
    'التاريخ': j['التاريخ'] || '—',
    'المجلد الجديد': j['المجلد الجديد'],
    'الاسم الجديد': j['الاسم الجديد'],
  } };
});

const XLSX = require('@e965/xlsx');
const rows = $input.all().map(i => i.json);
const header = ['الملف الأصلي', 'التصنيف', 'التاريخ', 'المجلد الجديد', 'الاسم الجديد'];
const aoa = [['سجل ترتيب التنزيلات (SAMPLE DATA)'], [], header];
const counts = {};
for (const r of rows) {
  aoa.push([r['الملف الأصلي'], r['التصنيف'], r['التاريخ'] || '—', r['المجلد الجديد'], r['الاسم الجديد']]);
  counts[r['التصنيف']] = (counts[r['التصنيف']] || 0) + 1;
}
aoa.push([]);
const parts = Object.keys(counts).map(k => k + ': ' + counts[k]).join('   ·   ');
aoa.push(['الإجمالي: ' + rows.length + ' ملفاً', parts]);
const wb = XLSX.utils.book_new();
const ws = XLSX.utils.aoa_to_sheet(aoa);
ws['!cols'] = [{ wch: 34 }, { wch: 12 }, { wch: 14 }, { wch: 22 }, { wch: 30 }];
XLSX.utils.book_append_sheet(wb, ws, 'سجل الترتيب');
const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
const bin = await this.helpers.prepareBinaryData(Buffer.from(buf), 'سجل-الترتيب.xlsx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
return [{ json: { files: rows.length, counts: counts }, binary: { data: bin } }];
